        "assets/theme.css": "/* Atelier – minimal editorial. Settings arrive as CSS variables (--vm-<setting-id>). */\n:root {\n  --bg: var(--vm-color-background, #f6f4ef);\n  --ink: var(--vm-color-text, #161513);\n  --accent: var(--vm-color-primary, #b4432b);\n  --muted: color-mix(in srgb, var(--ink) 58%, var(--bg));\n  --rule: color-mix(in srgb, var(--ink) 16%, var(--bg));\n  --display: var(--vm-heading-font, Georgia, serif);\n  --body: var(--vm-body-font, system-ui, sans-serif);\n  --gap: 1.5rem;\n  --reserve: calc(var(--vm-host-top-end, 56px) + 0.5rem);\n  color-scheme: light;\n}\n[data-setting-density=\"compact\"] { --gap: 0.85rem; }\n\n*, *::before, *::after { box-sizing: border-box; }\nhtml { background: var(--bg); scroll-behavior: smooth; }\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }\nbody { margin: 0; background: var(--bg); color: var(--ink); font: 400 1rem/1.6 var(--body); -webkit-font-smoothing: antialiased; }\nbutton { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 2px; }\n.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n.skip { position: absolute; inset-inline-start: 1rem; top: -4rem; background: var(--ink); color: var(--bg); padding: 0.5rem 1rem; z-index: 10; }\n.skip:focus { top: 1rem; }\n\n/* ---------- masthead */\n.masthead { max-width: 46rem; margin: 0 auto; padding: 1rem 1.5rem 0; }\n.topline { display: flex; align-items: center; gap: 1rem; min-height: 2.5rem; padding-inline-end: var(--reserve); font-size: 0.78rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }\n.langs { display: flex; gap: 0.25rem; margin-inline-start: auto; }\n.langs button { min-width: 2.25rem; min-height: 2.25rem; padding: 0 0.4rem; letter-spacing: 0.08em; color: var(--muted); border-bottom: 1px solid transparent; }\n.langs button[aria-current] { color: var(--ink); border-bottom-color: var(--accent); }\n.kicker { margin: 3.5rem 0 0; font-size: 0.8rem; letter-spacing: 0.24em; text-transform: uppercase; color: var(--accent); }\nh1 { margin: 0.5rem 0 0; font: 400 clamp(2.5rem, 12vw, var(--vm-title-size, 64px)) / 0.98 var(--display); letter-spacing: -0.02em; text-wrap: balance; }\n.tagline { margin: 1rem 0 0; max-width: 32rem; font-size: 1.1rem; color: var(--muted); }\n.masthead hr { border: 0; border-top: 1px solid var(--ink); margin: 2.5rem 0 0; }\n\n/* ---------- category nav */\n.catnav { position: sticky; top: 0; z-index: 5; background: color-mix(in srgb, var(--bg) 92%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--rule); }\n.catnav ul { display: flex; gap: 1.5rem; max-width: 46rem; margin: 0 auto; padding-block: 0; padding-inline: 1.5rem var(--reserve); list-style: none; overflow-x: auto; scrollbar-width: none; }\n.catnav ul::-webkit-scrollbar { display: none; }\n.catnav a { display: block; padding: 0.9rem 0; white-space: nowrap; color: var(--muted); text-decoration: none; font-size: 0.85rem; letter-spacing: 0.06em; border-bottom: 2px solid transparent; }\n.catnav a[aria-current] { color: var(--ink); border-bottom-color: var(--accent); }\n\n/* ---------- menu */\nmain { max-width: 46rem; margin: 0 auto; padding: 0 1.5rem; }\n.menu-title { margin: 4rem 0 0; font: 400 2.2rem/1.1 var(--display); }\n.menu-desc, .notice { margin: 0.5rem 0 0; color: var(--muted); }\n.notice { display: inline-block; padding: 0.15rem 0.6rem; border: 1px solid var(--rule); font-size: 0.85rem; }\n.menu.is-closed .items { opacity: 0.6; }\n.category { padding-top: 3.5rem; scroll-margin-top: 3.5rem; }\n.category-head { display: grid; grid-template-columns: auto 1fr; column-gap: 1rem; align-items: baseline; margin-bottom: calc(var(--gap) * 0.75); }\n.category-head .num { font: 400 0.85rem var(--body); color: var(--accent); letter-spacing: 0.1em; }\n.category-head h3 { margin: 0; font: 400 clamp(1.8rem, 7vw, 2.6rem) / 1.05 var(--display); letter-spacing: -0.01em; }\n.category-head p { grid-column: 2; margin: 0.35rem 0 0; color: var(--muted); font-style: italic; }\n\n.items { list-style: none; margin: 0; padding: 0; }\n.item { position: relative; display: flex; gap: 1rem; align-items: flex-start; padding: var(--gap) 0; border-top: 1px solid var(--rule); }\n.item:last-child { border-bottom: 1px solid var(--rule); }\n.item-body { flex: 1; min-width: 0; }\n.item-line { display: flex; align-items: baseline; gap: 0.5rem; }\n.item-name { margin: 0; font: 500 1.1rem/1.35 var(--body); min-width: 0; }\n.item-name button { text-align: start; }\n.item-name button:hover { color: var(--accent); }\n.leader { flex: 1; min-width: 1.5rem; border-bottom: 1px dotted var(--rule); transform: translateY(-0.3em); }\n.price { font-variant-numeric: tabular-nums; white-space: nowrap; font-weight: 500; }\n.item-desc { margin: 0.3rem 0 0; color: var(--muted); font-size: 0.95rem; max-width: 34rem; }\n.variants { list-style: none; display: flex; flex-wrap: wrap; gap: 0.35rem 1.25rem; margin: 0.5rem 0 0; padding: 0; font-size: 0.95rem; }\n.variants li { display: flex; gap: 0.5rem; }\n.variants li span:first-child { color: var(--muted); }\n.marks { margin-inline-start: 0.35rem; font: 500 0.68rem var(--body); color: var(--muted); vertical-align: super; letter-spacing: 0.04em; }\n.marks abbr { text-decoration: none; }\n.marks abbr + abbr::before { content: \",\"; }\n.meta { display: flex; flex-wrap: wrap; gap: 0.4rem; margin: 0.6rem 0 0; }\n.badge { font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; padding: 0.1rem 0.5rem; border: 1px solid var(--rule); color: var(--muted); }\n.badge-soldout { border-color: var(--accent); color: var(--accent); }\n.badge-unknown { text-transform: none; letter-spacing: 0; font-style: italic; border-style: dashed; }\n.is-soldout .item-name, .is-soldout .price { text-decoration: line-through; text-decoration-thickness: 1px; color: var(--muted); }\n.add { flex: none; display: grid; place-items: center; width: 2.25rem; height: 2.25rem; margin-top: -0.1rem; border: 1px solid var(--ink); border-radius: 50%; font-size: 1.2rem; line-height: 1; transition: background 0.15s, color 0.15s; }\n.add:hover, .add[data-vm-added] { background: var(--ink); color: var(--bg); }\n.thumb { position: relative; flex: none; margin: 0; width: 5.5rem; height: 5.5rem; }\n.thumb img { width: 100%; height: 100%; object-fit: cover; filter: grayscale(0.15); }\n.ai-label { position: absolute; inset-inline-start: 4px; bottom: 4px; padding: 1px 4px; border-radius: 3px; background: rgb(0 0 0 / 0.5); color: #fff; font: 600 9px/1.2 system-ui, sans-serif; letter-spacing: 0.02em; pointer-events: none; }\n.closing { margin: 4rem 0 0; text-align: center; font: italic 400 1.6rem var(--display); color: var(--muted); }\n\n/* ---------- footer */\n.site-footer { max-width: 46rem; margin: 3rem auto 0; padding: 2rem 1.5rem 4rem; border-top: 1px solid var(--ink); font-size: 0.88rem; color: var(--muted); display: grid; gap: 1.75rem; }\n.site-footer h2 { margin: 0 0 0.5rem; font: 500 0.75rem var(--body); letter-spacing: 0.18em; text-transform: uppercase; color: var(--ink); }\n.site-footer p { margin: 0.2rem 0; }\n.site-footer dl { margin: 0; display: grid; gap: 0.2rem; }\n.site-footer dl div { display: grid; grid-template-columns: 7rem 1fr; gap: 0.75rem; }\n.legend dl div { grid-template-columns: 1.75rem 1fr; }\n.site-footer dt { color: var(--ink); font-weight: 500; }\n.site-footer dd { margin: 0; }\naddress { font-style: normal; display: grid; gap: 0.1rem; }\naddress strong { color: var(--ink); font-weight: 500; }\n.legal { display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; }\n.link { text-decoration: underline; text-underline-offset: 3px; min-height: 2.25rem; }\n.powered { margin-inline-start: auto; opacity: 0.7; }\n\n@media (min-width: 720px) {\n  .masthead, main, .site-footer { padding-inline: 2rem; }\n  .site-footer { grid-template-columns: 1fr 1fr; }\n  .site-footer .notes, .site-footer .legal { grid-column: 1 / -1; }\n  .thumb { width: 7rem; height: 7rem; }\n}\n",
