        "templates/menu.liquid": "<a class=\"skip\" href=\"#menu\">{{ 'skipToMenu' | t }}</a>\n<header class=\"masthead\">\n  <div class=\"topline\">\n    {%- if table -%}<span class=\"table\">{{ 'table' | t: label: table.label }}</span>{%- endif -%}\n    {%- if languages.size > 1 -%}\n    <nav class=\"langs\" aria-label=\"{{ 'language' | t }}\">\n      {%- for l in languages -%}\n      <button type=\"button\" data-vm-lang=\"{{ l.code }}\" lang=\"{{ l.code }}\" title=\"{{ l.name }}\"{% if l.active %} aria-current=\"true\"{% endif %}>{{ l.code | upcase }}</button>\n      {%- endfor -%}\n    </nav>\n    {%- endif -%}\n  </div>\n  {%- if restaurant.cuisine -%}<p class=\"kicker\">{{ restaurant.cuisine }}</p>{%- endif -%}\n  <h1>{{ restaurant.name }}</h1>\n  {%- if settings.tagline != blank -%}<p class=\"tagline\">{{ settings.tagline }}</p>{%- endif -%}\n  <hr>\n</header>\n\n{% render 'nav' %}\n\n<main id=\"menu\">\n  {%- for menu in menus -%}\n  <section class=\"menu{% unless menu.active_now %} is-closed{% endunless %}\" aria-labelledby=\"m-{{ menu.id }}\">\n    <h2 class=\"menu-title{% if menus.size == 1 %} sr-only{% endif %}\" id=\"m-{{ menu.id }}\">{{ menu.name }}</h2>\n    {%- if menu.description and menus.size > 1 -%}<p class=\"menu-desc\">{{ menu.description }}</p>{%- endif -%}\n    {%- unless menu.active_now -%}<p class=\"notice\">{{ 'notAvailableNow' | t }}</p>{%- endunless -%}\n    {%- for category in menu.categories -%}\n    <section class=\"category\" id=\"c-{{ category.id }}\" data-category=\"{{ category.id }}\" aria-labelledby=\"h-{{ category.id }}\">\n      <header class=\"category-head\">\n        <span class=\"num\" aria-hidden=\"true\">{{ forloop.index | prepend: '0' | slice: -2, 2 }}</span>\n        <h3 id=\"h-{{ category.id }}\">{{ category.name }}</h3>\n        {%- if category.description -%}<p>{{ category.description }}</p>{%- endif -%}\n      </header>\n      <ul class=\"items\" role=\"list\">\n        {%- for item in category.items -%}{% render 'item', item: item %}{%- endfor -%}\n      </ul>\n    </section>\n    {%- endfor -%}\n  </section>\n  {%- endfor -%}\n  <p class=\"closing\" aria-hidden=\"true\">{{ 'closing' | t }}</p>\n</main>\n\n{% render 'footer' %}\n",
        "templates/partials/footer.liquid": "<footer class=\"site-footer\">\n  <div class=\"notes\">\n    <p>{% if currency == 'EUR' %}{{ 'pricesInclVat' | t }}{% else %}{{ 'pricesInclVatGeneric' | t }}{% endif %}</p>\n    {%- if has_unconfirmed_allergens -%}<p>{{ 'allergenNotice' | t }}</p>{%- endif -%}\n  </div>\n  {%- assign legend_count = legend.allergens.size | plus: legend.additives.size -%}\n  {%- if legend_count > 0 -%}\n  <section class=\"legend\" aria-labelledby=\"vm-legend\">\n    <h2 id=\"vm-legend\">{{ 'allergenLegend' | t }}</h2>\n    <dl>\n      {%- for a in legend.allergens -%}<div><dt>{{ a.letter }}</dt><dd>{{ a.label }}</dd></div>{%- endfor -%}\n      {%- for a in legend.additives -%}<div><dt>{{ a.letter }}</dt><dd>{{ a.label }}</dd></div>{%- endfor -%}\n    </dl>\n  </section>\n  {%- endif -%}\n  {%- if restaurant.opening_hours.size > 0 -%}\n  <section class=\"hours\" aria-labelledby=\"vm-hours\">\n    <h2 id=\"vm-hours\">{{ 'openingHours' | t }}</h2>\n    <dl>\n      {%- for h in restaurant.opening_hours -%}<div><dt>{{ h.day_name }}</dt><dd>{{ h.open }}–{{ h.close }}</dd></div>{%- endfor -%}\n    </dl>\n  </section>\n  {%- endif -%}\n  {%- if restaurant.address or restaurant.phone -%}\n  <address>\n    <strong>{{ restaurant.name }}</strong>\n    {%- if restaurant.address -%}<span>{{ restaurant.address }}</span>{%- endif -%}\n    {%- if restaurant.phone -%}<span>{{ restaurant.phone }}</span>{%- endif -%}\n  </address>\n  {%- endif -%}\n  <p class=\"legal\"><button type=\"button\" class=\"link\" data-vm-info>{{ 'imprint' | t }} · {{ 'privacy' | t }}</button>{% if show_branding %}<span class=\"powered\">{{ 'poweredBy' | t }}</span>{% endif %}</p>\n</footer>\n",
        "templates/partials/item-meta.liquid": "{%- comment -%} Badges: sold out, tags, unconfirmed allergens. {%- endcomment -%}\n{%- assign has_meta = false -%}\n{%- if item.available == false or item.tags.size > 0 or item.allergens_confirmed == false -%}{%- assign has_meta = true -%}{%- endif -%}\n{%- if has_meta -%}\n<p class=\"meta\">\n  {%- unless item.available -%}<span class=\"badge badge-soldout\">{{ 'soldOut' | t }}</span>{%- endunless -%}\n  {%- for tag in item.tags -%}<span class=\"badge badge-tag tag-{{ tag }}\">{{ 'tags.' | append: tag | t }}</span>{%- endfor -%}\n  {%- unless item.allergens_confirmed -%}<span class=\"badge badge-unknown\">{{ 'allergenUnknown' | t }}</span>{%- endunless -%}\n</p>\n{%- endif -%}\n",
        "templates/partials/item.liquid": "<li class=\"item{% unless item.available %} is-soldout{% endunless %}{% if settings.show_images and item.image_url %} has-image{% endif %}\">\n  {%- if settings.show_images and item.image_url -%}\n  <figure class=\"thumb\">\n    <img src=\"{{ item.image_url }}\" alt=\"\" loading=\"lazy\" decoding=\"async\" width=\"120\" height=\"120\">\n    {%- if item.image_is_ai -%}<span class=\"ai-label\" data-vm-ai-label title=\"{{ 'aiImage' | t }}\" aria-label=\"{{ 'aiImage' | t }}\">&#10022; {{ 'aiBadge' | t }}</span>{%- endif -%}\n  </figure>\n  {%- endif -%}\n  <div class=\"item-body\">\n    <div class=\"item-line\">\n      <h4 class=\"item-name\"><button type=\"button\" data-vm-item=\"{{ item.id }}\">{{ item.name }}</button>{% render 'marks', item: item %}</h4>\n      <span class=\"leader\" aria-hidden=\"true\"></span>\n      {%- if item.variants.size == 0 -%}\n      <span class=\"price\">{% if item.price %}{{ item.price_formatted }}{% else %}{{ 'priceOnRequest' | t }}{% endif %}</span>\n      {%- endif -%}\n    </div>\n    {%- if settings.show_descriptions and item.description -%}<p class=\"item-desc\">{{ item.description }}</p>{%- endif -%}\n    {%- if item.variants.size > 0 -%}\n    <ul class=\"variants\" role=\"list\">\n      {%- for v in item.variants -%}<li><span>{{ v.name }}</span><span class=\"price\">{{ v.price_formatted }}</span></li>{%- endfor -%}\n    </ul>\n    {%- endif -%}\n    {% render 'item-meta', item: item %}\n  </div>\n  {%- if item.orderable -%}\n  <button type=\"button\" class=\"add\" data-vm-add=\"{{ item.id }}\" aria-label=\"{{ 'quickAdd' | t: name: item.name }}\"><span aria-hidden=\"true\">+</span></button>\n  {%- endif -%}\n</li>\n",
        "templates/partials/marks.liquid": "{%- comment -%} Allergen letters + additive numbers (LMIV). Only confirmed data is shown. {%- endcomment -%}\n{%- assign mark_count = item.allergens.size | plus: item.additives.size -%}\n{%- if item.allergens_confirmed and mark_count > 0 -%}\n<span class=\"marks\" title=\"{{ 'allergens' | t }}: {% for a in item.allergens %}{{ a.label }}{% unless forloop.last %}, {% endunless %}{% endfor %}{% if item.additives.size > 0 %} · {{ 'additives' | t }}: {% for a in item.additives %}{{ a.label }}{% unless forloop.last %}, {% endunless %}{% endfor %}{% endif %}\">\n  {%- for a in item.allergens -%}<abbr title=\"{{ a.label }}\">{{ a.letter }}</abbr>{%- endfor -%}\n  {%- for a in item.additives -%}<abbr class=\"additive\" title=\"{{ a.label }}\">{{ a.letter }}</abbr>{%- endfor -%}\n</span>\n{%- endif -%}\n",
        "templates/partials/nav.liquid": "{%- assign cat_count = 0 -%}\n{%- for m in menus -%}{%- assign cat_count = cat_count | plus: m.categories.size -%}{%- endfor -%}\n{%- if cat_count > 1 -%}\n<nav class=\"catnav\" data-vm-catnav aria-label=\"{{ 'categories' | t }}\">\n  <ul>\n    {%- for m in menus -%}{%- for c in m.categories -%}\n    <li><a href=\"#c-{{ c.id }}\">{{ c.name }}</a></li>\n    {%- endfor -%}{%- endfor -%}\n  </ul>\n</nav>\n{%- endif -%}\n"
